export const Reference = () => (
  <AbsoluteFill>
    {SCENES.map((scene) => (
      <Sequence key={scene.id} from={scene.from} durationInFrames={scene.durationInFrames}>
        <Scene scene={scene} />
      </Sequence>
    ))}
  </AbsoluteFill>
);
